        "descAr": "وقف النبي ﷺ يُسوّي الصفوف بعود قائلاً استووا. ابتكر نظام الصفوف الثابتة بدلاً من الكرّ والفرّ. قضى الليل كله داعياً حتى سقط رداؤه. ثم أمطر حفنة تراب وتلا: شاهت الوجوه. انهزمت قريش وقُتل ٧٠ وأُسر ٧٠.",
