        "lessonAr": "الصدق مع الله يثمر صدقاً مع الناس، وأبو بكر صديق الأمة وأصدقها يقيناً.",
        "lessonEn": "Truthfulness with Allah bears truthfulness with people. Abu Bakr was the Siddiq of the Ummah and the most certain in faith.",
