        "descAr": "بعد وفاة النبي ﷺ اجتمع الأنصار في سقيفة بني ساعدة لاختيار خليفة. فلما بلغ الخبر أبا بكر وعمر وأبا عبيدة، أسرعوا إليهم. خطب أبو بكر خطبته المشهورة، ثم بايعه عمر ومن حضر، وفي اليوم التالي بويع بيعة عامة في المسجد. ثم صعد المنبر وألقى خطبته الخالدة: 'أيها الناس، إني قد وُلِّيت عليكم ولست بخيركم، فإن أحسنت فأعينوني، وإن أسأت فقوِّموني... أطيعوني ما أطعت الله ورسوله، فإن عصيت الله ورسوله فلا طاعة لي عليكم'. هذه الخطبة وضعت أسس الحكم الراشد: العدل، والشفافية، والمساءلة.",
        "descEn": "After the Prophet's ﷺ death, the Ansar gathered at Saqifat Bani Sa'idah to choose a caliph. When Abu Bakr, Umar, and Abu Ubaydah heard, they hurried to them. Abu Bakr delivered his famous speech, then Umar and those present pledged allegiance. The next day, a general pledge took place in the mosque. He ascended the pulpit and gave his historic address: 'O people, I have been given authority over you, and I am not the best among you. If I do well, support me; if I do wrong, correct me... Obey me as long as I obey Allah and His Messenger; if I disobey Allah and His Messenger, then no obedience is due from you.' This address laid the foundations of just governance: justice, transparency, and accountability.",
