        "descAr": "بعد وفاة النبي ﷺ ارتدت بعض القبائل ومنعت الزكاة. قال أبو بكر: 'والله لو منعوني عقالاً كانوا يؤدونه إلى رسول الله ﷺ لقاتلتهم على منعه'. قسم الجيش إلى ١١ لواء على رأسها خالد بن الوليد وعكرمة بن أبي جهل وعمرو بن العاص وغيرهم. أشهر معارك الردة: معركة اليمامة ضد مسيلمة الكذاب (قُتل فيها ٧٠ حافظاً للقرآن)، ومعركة البُزاخة ضد طُلَيحة الأسدي. نجحت الخطة في أشهر معدودة، وتوحدت الجزيرة تحت راية المدينة، ومُهّد الطريق للفتوحات الكبرى.",
        "descEn": "After the Prophet's death, some tribes apostatized and refused to pay Zakat. Abu Bakr declared: 'By Allah, if they withhold even a hobbling-cord they used to pay the Messenger of Allah, I will fight them for withholding it.' He divided the army into 11 corps led by Khalid ibn al-Walid, Ikrimah ibn Abi Jahl, Amr ibn al-As, and others. The most famous Ridda battle: the Battle of Yamamah against Musaylimah the Liar (70 Qur'an memorizers were martyred), and the Battle of Buzakhah against Tulayhah al-Asadi. The strategy succeeded within months, uniting the peninsula under Madinah's banner and paving the way for the great conquests.",
