        "descAr": "بعد حروب الردة وجه أبو بكر الجيوش إلى العراق تحت قيادة خالد بن الوليد، ففتح الحيرة في سلسلة معارك خاطفة (ذات السلاسل — المذار — الولجة — أُلَّيس). ثم أمر أبا عبيدة بن الجراح بالتوجه إلى الشام، وأرسل أربعة جيوش يقودها أبو عبيدة ويزيد بن أبي سفيان وشرحبيل بن حسنة وعمرو بن العاص. وحين اشتدت الحاجة، أمر خالداً بقطع صحراء السماوة في ٥ أيام لينتقل من العراق إلى الشام ويتولى القيادة الموحدة. وقبيل وفاته بأيام بدأت معركة اليرموك الفاصلة، لكن الصديق توفي في المدينة يوم الاثنين ٢٢ جمادى الآخرة ١٣ هـ عن ٦٣ سنة، ودُفن بجانب النبي ﷺ، دون أن يعلم بانتصار اليرموك الساحق.",
        "descEn": "After the Ridda wars, Abu Bakr sent armies to Iraq under Khalid ibn al-Walid, who conquered al-Hirah in a series of lightning battles (Dhat al-Salasil, al-Madhar, al-Walajah, Ullays). He then ordered Abu Ubaydah ibn al-Jarrah toward Syria, sending four armies led by Abu Ubaydah, Yazid ibn Abi Sufyan, Shurahbil ibn Hasanah, and Amr ibn al-As. When the need grew urgent, he ordered Khalid to cross the Samawah desert in 5 days, moving from Iraq to Syria to assume unified command. Days before his death, the decisive Battle of Yarmouk began, but Abu Bakr died in Madinah on Monday, 22 Jumada al-Akhirah 13 AH, at age 63, buried beside the Prophet ﷺ — never learning of the magnificent victory at Yarmouk.",
