        "descAr": "في صلاة الفجر من ذي الحجة سنة ٢٣ هـ، وقف عمر يؤم الناس في المسجد النبوي كما كان يفعل، فطعنه أبو لؤلؤة فيروز (غلام المغيرة بن شعبة المجوسي) ثلاث طعنات بخنجر ذي نصلين. وخرج القاتل يطعن من لقيه. حمل عمر إلى بيته، فجاء عبد الله بن عباس وعبد الرحمن بن عوف وكان مما قال: 'اللهم اغفر لي، واجعلني مع النبي ﷺ وأبي بكر'. ثم أنشأ الخلافة شورى بين ستة: عثمان وعلي وطلحة والزبير وسعد وعبد الرحمن بن عوف. وتوفي بعد ثلاثة أيام، ودفن بجانب النبي ﷺ وأبي بكر، ليتم بذلك ثالث الأضلع في قبر الحجرة النبوية الشريفة.",
        "descEn": "At Fajr prayer in Dhul-Hijjah 23 AH, Umar was leading the people in the Prophet's Mosque as usual, when Abu Lu'lu'ah Firuz (a Zoroastrian slave of al-Mughirah ibn Shu'bah) stabbed him three times with a double-bladed dagger. The killer ran out stabbing everyone he met. Umar was carried to his home, where Abdullah ibn Abbas and Abd al-Rahman ibn Awf attended him. He said: 'O Allah, forgive me, and place me with the Prophet and Abu Bakr.' He then formed a shura (council) of six: Uthman, Ali, Talhah, al-Zubayr, Sa'd, and Abd al-Rahman ibn Awf. He died three days later and was buried beside the Prophet and Abu Bakr, completing the third grave in the Noble Chamber.",
