        "distAr": "من بدر إلى خيبر",
        "distEn": "From Badr to Khaybar",
        "descAr": "كان علي فارس الإسلام الأول: شهد بدراً وأحداً والخندق وخيبر وفتح مكة. في بدر كان من أبطال المبارزة، وفي أحد حَمى النبي ﷺ ببدنه، وفي الخندق بارز عمرو بن عبد ود وصرعه. وأعظم مشاهد بطولته فتح خيبر حيث قال النبي ﷺ: 'لأعطين الراية غداً رجلاً يحب الله ورسوله ويحبه الله ورسوله' فأعطاها لعلي ففتح الله على يديه. وكان علي إلى جانب شجاعته من أعلم الصحابة وأفقههم، وكان الخلفاء يستشيرونه في المعضلات، وقال النبي ﷺ: 'أنا مدينة العلم وعلي بابها'.",
        "descEn": "Ali was Islam's foremost knight: he witnessed Badr, Uhud, the Trench, Khaybar, and the Conquest of Makkah. At Badr he was a champion of single combat; at Uhud he shielded the Prophet with his body; at the Trench he dueled Amr ibn Abd Wudd and killed him. His greatest heroic moment was the conquest of Khaybar, where the Prophet said: 'Tomorrow I will give the banner to a man who loves Allah and His Messenger and whom Allah and His Messenger love' — and gave it to Ali, and Allah granted victory through him. Alongside his bravery, Ali was one of the most knowledgeable and learned Companions; the caliphs would consult him on difficult matters. The Prophet said: 'I am the city of knowledge, and Ali is its gate.'",
