        "timeEn": "17 Ramadan 40 AH",
        "distAr": "الكوفة",
        "distEn": "Kufa",
        "descAr": "توعد الخوارج بقتل علي ومعاوية وعمرو بن العاص. وفي فجر ١٧ رمضان ٤٠ هـ دخل علي المسجد في الكوفة يوقظ الناس للصلاة، فضربه عبد الرحمن بن ملجم الخارجي بسيف مسموم على رأسه. فقال علي: 'فزت ورب الكعبة'. أوصى بالحسن خليفة من بعده ومات بعد يومين. قال لولده الحسن: 'يا بني، أوصيك بتقوى الله، وإقام الصلاة، وإيتاء الزكاة، وحسن الخلق'. ودُفن في الكوفة. كانت خلافته ٤ سنوات و٩ أشهر، حافلة بالأحداث والفتن التي لم تكن باختياره.",
        "descEn": "The Kharijites conspired to assassinate Ali, Muawiyah, and Amr ibn al-As. At dawn on 17 Ramadan 40 AH, Ali entered the mosque in Kufa to wake people for prayer, when Abd al-Rahman ibn Muljam al-Khariji struck him on the head with a poisoned sword. Ali said: 'By the Lord of the Kaaba, I have succeeded.' He appointed al-Hasan as his successor and died two days later. He advised his son al-Hasan: 'My son, I advise you to fear Allah, establish prayer, give zakah, and be of good character.' He was buried in Kufa. His caliphate lasted 4 years and 9 months, filled with events and tribulations beyond his control.",
