        "descEn": "Al-Hasan ibn Ali was born in mid-Ramadan 3 AH in Madinah. The Prophet named him 'Hasan', and he resembled his grandfather, the Messenger of Allah, in appearance and character. The Prophet said: 'Hasan and Husayn are the masters of the youth of Paradise.' He would carry him on his shoulders and say: 'O Allah, I love him, so love him.' Al-Hasan was raised in the purest household: his father Ali ibn Abi Talib, his mother Fatimah al-Zahra', the best of women. The Prophet raised him in his care, and he imbibed knowledge, forbearance, and eloquence. He was the most forbearing, generous, and resembling of people to the Messenger of Allah in guidance and demeanor.",
