        "descEn": "After Ali's martyrdom, the people of Iraq pledged allegiance to al-Hasan ibn Ali as caliph in Kufa. His caliphate was short (six months) but decisive. Al-Hasan faced a great challenge: the Ummah was divided between his army in Kufa and the Syrian army under Muawiyah ibn Abi Sufyan, who also claimed the caliphate. Al-Hasan knew that war between two massive armies would kill thousands of Muslims. So he chose the path of peace — the most difficult decision any ruler has ever made in Islamic history.",
