        "descAr": "سار الحسن بجيشه من الكوفة لملاقاة معاوية في المدائن. وكان الخندق بين جيشي الكوفة والشام على وشك الاشتعال في حرب أهلية مهلكة. هنا تجلت عبقرية الحسن: أرسل إلى معاوية يعرض الصلح. واتفقا على أن: يتنازل الحسن عن الخلافة لمعاوية بشرط أن يعمل بكتاب الله وسنة رسوله، وأن يعهد بالخلافة من بعده إلى...، وأن يُؤمَّن أهل المدينة وغيرهم، وألا يُطارد أحد من أتباع علي. فقبل معاوية. وسُمي ذلك العام بـ'عام الجماعة' لالتئام شمل المسلمين. تحققت نبوءة النبي ﷺ: 'إن ابني هذا سيد، ولعل الله أن يصلح به بين فئتين عظيمتين من المسلمين'.",
        "descEn": "Al-Hasan marched with his army from Kufa toward Muawiyah at Mada'in. The trench between the armies of Kufa and Syria was about to ignite a devastating civil war. Here, al-Hasan's genius shone: he sent to Muawiyah offering peace. They agreed that: al-Hasan would abdicate the caliphate to Muawiyah on condition that he rule by the Book of Allah and the Sunnah, that the caliphate would be entrusted after him to..., that the people of Madinah and others would be safe, and that Ali's followers would not be persecuted. Muawiyah accepted. That year was called the 'Year of Unity' ('Am al-Jama'ah') because the Muslim community was reunited. The Prophet's prophecy was fulfilled: 'This son of mine is a master, and perhaps Allah will reconcile two great factions of the Muslims through him.'",
