        "lessonAr": "العزة في ترك السلطة لا في الوصول إليها: الحسن ترك الملك وجلس في البقيع يعبد الله.",
        "lessonEn": "Dignity lies in leaving power, not in attaining it: al-Hasan left the throne and sat in al-Baqi' worshipping Allah.",
