          "descAr": "تولى عبد الملك بن مروان الخلافة سنة 65 هـ والدولة الإسلامية تعاني من انقسامات حادة: فتنة ابن الزبير في الحجاز، وحركة المختار الثقفي في العراق، وتزايد النفوذ البيزنطي على الثغور. كان عبد الملك رجلاً حازماً ذا رؤية سياسية وإدارية فذة. استطاع خلال سنوات قليلة أن يعيد توحيد الدولة تدريجياً، مستعيناً بولاة أقوياء أمثال الحجاج بن يوسف الثقفي. بدأ مشروعاً حضارياً شاملاً لترسيخ الهوية الإسلامية للدولة. يلقبه المؤرخون بـ 'المؤسس الثاني' للدولة الأموية بعد معاوية بن أبي سفيان، لأنه أعاد بناء هيكل الدولة من جديد بعد أن كادت تتفكك.",
          "descEn": "Abd al-Malik ibn Marwan assumed the caliphate in 65 AH while the Islamic state suffered from severe divisions: the fitna of Ibn al-Zubayr in the Hejaz, the movement of al-Mukhtar al-Thaqafi in Iraq, and growing Byzantine influence at the frontiers. Abd al-Malik was a decisive man with extraordinary political and administrative vision. Over a few years, he gradually reunified the state with the help of strong governors like al-Hajjaj ibn Yusuf al-Thaqafi. He began a comprehensive civilizational project to establish the Islamic identity of the state. Historians call him the 'Second Founder' of the Umayyad state after Muawiyah ibn Abi Sufyan, because he rebuilt the state structure from near collapse.",
