          "descAr": "أمر عبد الملك بن مروان بتعريب الدواوين (نحو سنة 81 هـ)، أي تحويل اللغة الإدارية من اليونانية والفارسية إلى اللغة العربية في جميع أقاليم الدولة. كانت هذه خطوة حضارية كبرى لترسيخ الهوية الإسلامية وجعل اللغة العربية لغة العلم والإدارة والحكم. وفي سنة 76 هـ أمر بسك أول دينار إسلامي أموي خالص، نقش عليه آيات قرآنية بدلاً من الصور البشرية التي كانت على العملات البيزنطية والفارسية. كان هذا الإجراء ثورياً لأنه رسخ الاستقلال الاقتصادي والثقافي للدولة الإسلامية. الدينار الذهبي الأموي أصبح العملة الأقوى في العالم لقرون طويلة.",
          "descEn": "Abd al-Malik ibn Marwan ordered the arabization of the diwans (c. 81 AH), converting the administrative language from Greek and Persian to Arabic in all regions of the state. This was a major civilizational step to establish Islamic identity and make Arabic the language of knowledge, administration, and governance. In 76 AH, he ordered the minting of the first pure Islamic Umayyad dinar, inscribed with Quranic verses instead of the human images found on Byzantine and Persian coins. This was a revolutionary measure that cemented the economic and cultural independence of the Islamic state. The Umayyad gold dinar became the world's strongest currency for centuries.",
