          "descAr": "تولى سليمان بن عبد الملك الخلافة سنة 96 هـ وكان طموحاً كبيراً لفتح القسطنطينية. أرسل أخاه مسلمة بن عبد الملك على رأس جيش كبير وحصار بحري وبري للقسطنطينية سنة 98 هـ. شارك في هذه الحملة متطوعون من جميع أقاليم الدولة الإسلامية. استمر الحصار شهوراً طويلة، لكن حيل ليون الثالث ودفاعاته والمجاعة الشديدة في معسكر المسلمين أدت إلى فشل الحصار في النهاية. في أواخر عهد سليمان كتب وصية الخلافة لعمر بن عبد العزيز بناءً على نصيحة العالم الرباني الرجاء بن حيوة الذي أدرك في عمر بن عبد العزيز الصلاح والعدل. كانت هذه الفترة من أهم مفاصل التاريخ الأموي لأنها نقلت الحكم إلى رجل مختلف تماماً.",
          "descEn": "Sulayman ibn Abd al-Malik assumed the caliphate in 96 AH with a great ambition to conquer Constantinople. He sent his brother Maslamah ibn Abd al-Malik at the head of a large army with a naval and land siege of Constantinople in 98 AH. Volunteers from all regions of the Islamic state participated. The siege lasted many months, but Leo III's stratagems and defenses, and severe famine in the Muslim camp, eventually led to its failure. Near the end of Sulayman's reign, he wrote the succession covenant for Umar ibn Abd al-Aziz based on the advice of the righteous scholar Raja ibn Haywah, who recognized in Umar ibn Abd al-Aziz righteousness and justice. This moment was one of the most important turning points in Umayyad history, as it transferred rule to a completely different kind of man.",
