          "descAr": "تولى عمر بن عبد العزيز الخلافة سنة 99 هـ فكان أشبه بانقلاب أخلاقي في تاريخ الدولة الأموية. كان أول ما فعله أنه رفض المراكب والرفاهية الملكية التي كان يتمتع بها الخلفاء قبله. بدأ بنفسه أولاً: رد الأموال والإقطاعيات التي كانت في حوزته وفي حوزة أسرته إلى بيت مال المسلمين. كانت زوجته فاطمة بنت عبد الملك قدوة حين تنازلت عن حليها ومجوهراتها تضامناً مع منهجه الزاهد. أرسل إلى جميع العمال والولاة يأمرهم برد المظالم وإلغاء المكوس والضرائب الظالمة. في أشهر قليلة تحولت الدولة من القصور الملكية إلى الزهد والعدل الذي ذكّر الناس بأيام عمر بن الخطاب.",
          "descEn": "Umar ibn Abd al-Aziz assumed the caliphate in 99 AH, marking an ethical revolution in Umayyad history. His first act was to reject the royal carriages and luxury that previous caliphs had enjoyed. He began with himself: he returned the wealth and estates in his possession and his family's to the public treasury. His wife Fatimah bint Abd al-Malik set an example by relinquishing her jewelry and ornaments in solidarity with his ascetic approach. He sent letters to all officials and governors ordering the restitution of rights and the abolition of unjust taxes and levies. Within months, the state transformed from royal palaces to the asceticism and justice that reminded people of the days of Umar ibn al-Khattab.",
