          "distAr": "📍 الشام",
          "distEn": "📍 Levant",
          "descAr": "بعد وفاة هشام بن عبد الملك دخلت الدولة الأموية في مرحلة الاضطراب والصراع الداخلي الحاد. قتل الخليفة الوليد بن يزيد بن عبد الملك في مؤامرة من داخل البيت الأموي. ثم توالت الخلفاء الضعاف: يزيد بن الوليد (الناقص) ثم إبراهيم بن الوليد. في هذه الأثناء اشتعلت العصبية القبلية بين المضرية واليمانية بشكل غير مسبوق، وهي النزعة القبلية التي قسمت الجيش الأموي والمجتمع في الشام. انشغل القادة في صراعاتهم الداخلية على السلطة والمال. في الجبهة الشرقية كانت الدعوة العباسية تنمو وتنظم صفوفها في خراسان بعيداً عن عيون الأمويين المنشغلين بفتنهم الداخلية.",
          "descEn": "After Hisham ibn Abd al-Malik's death, the Umayyad state entered a period of acute internal turmoil and conflict. Caliph al-Walid ibn Yazid was killed in a conspiracy from within the Umayyad house. Then weak caliphs followed: Yazid ibn al-Walid (al-Naqis) then Ibrahim ibn al-Walid. During this time, tribal partisanship between the Mudaris and Yemenis flared up unprecedentedly, a tribal rift that divided the Umayyad army and society in the Levant. Leaders became absorbed in their internal power and wealth struggles. On the eastern front, the Abbasid call (dawah) was growing and organizing its ranks in Khurasan, far from the eyes of the Umayyads preoccupied with their internal fitnas.",
          "charsAr": [
            {"i":"👑","n":"الوليد بن يزيد","r":"خليفة قتل في مؤامرة داخل البيت الأموي — بداية النهاية"},
            {"i":"⚔️","n":"المضرية واليمانية","r":"العصبية القبلية التي قسمت الجيش الأموي"}
          ],
          "charsEn": [
            {"i":"👑","n":"Al-Walid ibn Yazid","r":"Caliph killed in an internal Umayyad conspiracy — beginning of the end"},
            {"i":"⚔️","n":"Mudaris vs Yemenis","r":"Tribal partisanship that divided the Umayyad army"}
          ],
          "lessonAr": "النزاع الداخلي يورث الفشل — إحياء العصبية القبلية والصراع داخل البيت الحاكم كان السكين التي قطعت أواصر الدولة",
          "lessonEn": "Internal conflict begets failure — reviving tribal partisanship and conflict within the ruling house was the knife that severed the state's bonds",
          "srcs": ["الطبري (تاريخ الأمم والملوك)", "ابن الأثير (الكامل في التاريخ)"],
          "mapFocus": {"x":320,"y":200,"scale":1.0}
