          "mdAr": "آخر خلفاء بني أمية — 91 عاماً من الحكم",
          "mdEn": "The last Umayyad caliph — 91 years of rule",
          "amb": "night",
          "timeAr": "جمادى الآخرة ١٣٢ هـ",
          "timeEn": "January 750 CE",
          "distAr": "📍 من الشام إلى مصر",
          "distEn": "📍 From the Levant to Egypt",
          "descAr": "تولى مروان بن محمد الخلافة سنة 127 هـ بعد اشتداد الفتنة الداخلية. كان مروان قائداً عسكرياً فذاً، لُقب بـ 'مروان الحمار' (أي الصبور في الحروب) لثباته وجلده في المعارك. لكنه تولى الخلافة والدولة في حالة موت سريري جراء الصراعات الداخلية. في عام 132 هـ التقى جيش مروان بالجيش العباسي بقيادة عبد الله بن علي في معركة الزاب في العراق. انتهت المعركة بهزيمة ساحقة للأمويين. هرب مروان إلى الشام ثم إلى مصر حيث قُتل في قرية بوصير. بذلك انتهت الدولة الأموية في الشرق بعد أن حكمت 91 عاماً (41-132 هـ). كان هذا درساً أن الدولة التي قامت على الجهاد ونشر الإسلام سقطت حين تخلت عن معايير العدل.",
          "descEn": "Marwan ibn Muhammad assumed the caliphate in 127 AH after internal strife intensified. Marwan was an extraordinary military commander, nicknamed 'Marwan the Donkey' (meaning patient in wars) for his steadfastness and endurance in battle. But he assumed the caliphate when the state was in a state of clinical death due to internal conflicts. In 132 AH, Marwan's army met the Abbasid army under Abd Allah ibn Ali at the Battle of the Zab in Iraq. The battle ended in a devastating Umayyad defeat. Marwan fled to the Levant and then to Egypt, where he was killed in the village of Busir. Thus ended the Umayyad state in the East after ruling for 91 years (41-132 AH). This was a lesson that a state built on jihad and spreading Islam fell when it abandoned the standards of justice.",
          "charsAr": [
            {"i":"⚔️","n":"مروان بن محمد","r":"آخر خلفاء بني أمية — قائد عسكري فذ لكن الدولة كانت في حالة موت سريري"}
          ],
          "charsEn": [
            {"i":"⚔️","n":"Marwan ibn Muhammad","r":"The last Umayyad caliph — brilliant commander, but the state was in clinical death"}
          ],
          "lessonAr": "سنن الله لا تحابي أحداً — الدولة التي قامت على جهاد ونشر الإسلام سقطت حين تخلت عن معايير العدل والشورى",
          "lessonEn": "Allah's laws favor no one — a state built on jihad and spreading Islam fell when it abandoned the standards of justice and consultation",
          "srcs": ["ابن الأثير (الكامل في التاريخ)", "ابن كثير (البداية والنهاية)"],
