        "descEn": "The Abbasid call (da'wah) was launched from Khurasan under Abu Muslim al-Khurasani, culminating in 132 AH when the Abbasid army entered Kufa and proclaimed Abu al-Abbas Abd Allah ibn Muhammad as caliph. He was given the title al-Saffah (the Blood-Shedder). With this momentous event, the caliphate moved from the Umayyads in Damascus to the Banu Hashim in Iraq. A new chapter in Islamic history began — one that would last over 500 years.",
