        "descAr": "بعد أن ثبت أبو جعفر المنصور دعائم الدولة العباسية وقضى على الثورات الداخلية، شرع في بناء عاصمة جديدة تعبر عن هيبة الدولة الإسلامية الجديدة. اختار موقعاً استراتيجياً على ضفاف نهر دجلة قرب قرية بغداد، وبنى مدينة دائرية فريدة عرفت بـ 'المدينة المدورة'. كان التصميم ثورياً: دائرة بقطر 2.7 كيلومتر، بأربعة أبواب تتجه إلى الكوفة والبصرة والشام وخراسان، وفي المركز قصر الخلافة والجامع الكبير. تم بناء المدينة في 4 سنوات بمشاركة مائة ألف عامل ومهندس. أصبحت بغداد أسرع مدن العالم نمواً في العصور الوسطى.",
        "descEn": "After Abu Ja'far al-Mansur solidified the Abbasid state and crushed internal rebellions, he set out to build a new capital reflecting the grandeur of the new Islamic state. He chose a strategic site on the banks of the Tigris near the village of Baghdad, and built a unique circular city known as 'The Round City'. The design was revolutionary: a circle 2.7 km in diameter, with four gates facing Kufa, Basra, Damascus, and Khurasan, and at its center the Caliphal Palace and the Great Mosque. The city was built in 4 years with 100,000 workers and engineers. Baghdad became the fastest-growing city in the medieval world.",
