        "descEn": "The Abbasid caliphs established the House of Wisdom (Bayt al-Hikma) in Baghdad, a unique scholarly institution that gathered scientists from across the world. The works of Aristotle, Plato, Galen, and Ptolemy were translated from Greek, along with Indian and Persian philosophy. This era saw the rise of great jurists like Abu Hanifa, Malik, and al-Shafi'i, and scholars of tafsir and hadith who codified the Islamic sciences. Baghdad became the beacon of knowledge in the world, attracting students from China to Andalusia.",
