        "descEn": "The Abbasid state reached its peak under Harun al-Rashid, who assumed the caliphate in 170 AH. It was a golden age by every measure: Abbasid armies struck in every direction, trade flourished between China, Africa, and Europe, and the House of Wisdom was at its zenith. Baghdad was the richest and most advanced city in the world. The state stretched from Transoxiana in the east to Ifriqiya in the west, and from the Caucasus in the north to Yemen in the south. Al-Rashid performed Hajj one year and led military campaigns the next, his jihad against the Byzantines never ceasing.",
