        "descEn": "The distorted image of Harun al-Rashid portrayed in folk literature must be corrected. Sunni historians like Ibn Kathir affirmed that al-Rashid was a king, leader, and mujtahid. He performed Hajj one year and personally led his army in jihad the next. He stopped the Byzantine Emperor Nikephoros when he dared to threaten the Islamic state, imposing jizyah on him and humiliating him. His court was one of knowledge and jurisprudence, hosting Imam Abu Yusuf and other great scholars. He built fortresses on the frontiers (al-thughur) to protect Islamic borders. His days were not all frivolity — they were days of jihad, justice, and learning.",
