        "descEn": "After the death of Harun al-Rashid, conflict erupted between his two sons, al-Amin and al-Ma'mun, over the caliphate. Al-Rashid had divided the state between them, but greed for power drove al-Amin to attempt deposing his brother. Both brothers amassed armies, and Baghdad was besieged for a full year by al-Ma'mun's forces under Tahir ibn al-Husayn. Baghdad fell and al-Amin was brutally killed. This fitna was a tragic turning point: for the first time, Muslim armies besieged the capital of the caliphate, and an Abbasid caliph was killed by a Muslim army. The Abbasid state emerged from this ordeal shaken, its prestige lost.",
