        "descEn": "Al-Ma'mun's reign was an age of contradictions: scientifically, the House of Wisdom reached its zenith, the greatest works of philosophy and science were translated, and al-Khwarizmi in mathematics and al-Kindi in philosophy emerged. But in matters of creed, al-Ma'mun forced scholars to profess that the Qur'an was created, adopting Mu'tazilite thought. He began the 'Mihna' (Inquisition) — a test for judges and scholars. Imam Ahmad ibn Hanbal stood alone, steadfast against this intellectual terrorism, refusing to say the Qur'an was created, and was imprisoned and tortured. This steadfastness preserved the creed of the ummah to this day.",
