        "descEn": "Al-Mu'tasim assumed the caliphate after al-Ma'mun. He became famous for the story of a Muslim woman who cried 'Ya Mu'tasimah!' when a Roman soldier mistreated her in Amorium. When the caliph heard the news, he was filled with righteous anger and replied with a single word: 'Labayk (At your service).' Al-Mu'tasim led a massive army of 80,000 soldiers and conquered the city of Amorium deep in Anatolia after a fierce siege. This was the greatest victory against the Byzantines in over a century. The story entered history as a symbol of the ruler's responsibility to protect his subjects, even those at the farthest frontiers.",
