        "descEn": "Al-Mutawakkil assumed the caliphate after al-Wathiq, and was one of the greatest Abbasid caliphs in defending the Sunnah. His first action was ending the Mihna (Inquisition on the createdness of the Qur'an) which had lasted 15 years, and honored Imam Ahmad ibn Hanbal after his ordeal. He commanded the public practice of the Sunnah, suppressed innovations, and honored scholars and hadith narrators. He expanded the city of Samarra and built its great mosque with the famous Malwiya minaret — a symbol of Sunni architectural power. But he did not escape the treachery of the Turkish soldiers who assassinated him in his palace in 247 AH.",
