        "descEn": "After the assassination of al-Mutawakkil, the Abbasid state entered its most turbulent period, known as the 'Anarchy of Samarra'. Turkish military commanders (Wasif, Bagha al-Sharabi, and others) became the de facto rulers. The caliphate was shuffled through 5 caliphs in just 9 years: al-Muntasir, al-Musta'in, al-Mu'tazz, al-Muhtadi, then al-Mu'tamid. Each one was either killed, deposed, or forced to abdicate. The caliphate became a political game in the hands of the military, and the prestige of the Banu Abbas completely collapsed.",
