        "descEn": "In the darkest days of the caliphate, al-Muwaffaq (brother of Caliph al-Mu'tamid) emerged as a brilliant military commander who saved the state from collapse. The most dangerous crisis facing the state was the Zanj Revolt — a rebellion of black slaves in the Basra and Ahwaz regions that lasted 14 years and claimed hundreds of thousands of lives. Al-Muwaffaq personally led the army, fought fierce battles, and finally crushed the revolt in 270 AH. He restructured the state, reorganized the army, and largely restored the caliphate's prestige.",
