        "descEn": "After al-Muwaffaq, his son al-Mu'tadid assumed the caliphate and became one of the strongest late Abbasid caliphs. He moved the capital back from Samarra to Baghdad, ending the era of turmoil. He restored the state's power, subdued rebels on the frontiers, and personally led armies. He strictly managed the state treasury, leaving a full treasury for his successors. He tried to rebuild the caliphal state on principles of centralization and strength, but the roots of weakness were deep and the challenges too great for one caliph alone.",
