        "descAr": "في العقود الأخيرة قبل دخول البويهيين، تآكلت سلطة الخلفاء العباسيين بشكل متسارع. أصبح نفوذ الخليفة لا يتجاوز أسوار بغداد، بينما ظهرت دويلات مستقلة في أطراف الدولة: الإخشيديون في مصر والشام، الحمدانيون في الموصل وحلب، السامانيون في خراسان وما وراء النهر. كان هؤلاء الحكام يخطبون للخليفة في المنابر ويذكرون اسمه في السكة، لكنهم في الواقع كانوا يحكمون استقلالاً تاماً. أصبح الخليفة يقتات على الهدايا والضرائب القليلة.",
        "descEn": "In the decades before the Buyid takeover, the authority of the Abbasid caliphs eroded rapidly. The caliph's influence barely extended beyond the walls of Baghdad, while independent dynasties emerged on the peripheries: the Ikhshidids in Egypt and Syria, the Hamdanids in Mosul and Aleppo, the Samanids in Khurasan and Transoxiana. These rulers mentioned the caliph in Friday sermons and on coins, but in reality they ruled with complete independence. The caliph subsisted on gifts and meager taxes.",
