        "descAr": "في عام 334 هـ دخل أحمد بن بويه (معز الدولة) بغداد بدون مقاومة تذكر، وأعلن سيطرته على الخلافة. كان البويهيون شيعة اثني عشرية، وقد تحولوا إلى الحكام الفعليين للدولة. احتفظوا بالخليفة العباسي كرمز شرعي، لكنهم جردوه من كل سلطة حقيقية. أصبح الخليفة يتقاضى راتباً من البويهيين، ويصدر قراراتهم باسمه. استمرت الهيمنة البويهية 113 عاماً، وطوّرت نظام 'أمير الأمراء' (السلطان الفعلي) الذي يحكم باسم الخليفة الرمزي.",
        "descEn": "In 334 AH, Ahmad ibn Buwayh (Mu'izz al-Dawla) entered Baghdad without significant resistance and declared his control over the caliphate. The Buyids were Twelver Shi'a, and they became the de facto rulers of the state. They kept the Abbasid caliph as a symbolic authority but stripped him of all real power. The caliph now received a salary from the Buyids and issued their decisions in his name. Buyid hegemony lasted 113 years and developed the 'Amir al-Umara' system (the actual sultan) who ruled in the name of the symbolic caliph.",
