        "descAr": "دامت الهيمنة البويهية على بغداد أكثر من قرن. لم يستطع البويهيون إلغاء الخلافة رغم مذهبهم الشيعي، لأن رمزية الخلافة السنية كانت راسخة في وجدان الأمة. خلال هذه الفترة، ازدهرت الثقافة والعلوم رغم الضعف السياسي. برز الشريف الرضي (جامع نهج البلاغة) والمرتضى والشيخ الطوسي من علماء الشيعة، كما برز الفارابي وابن سينا من الفلاسفة. لكن الضرائب الباهظة والصراعات الداخلية بين القادة البويهيين أضعفت الدولة تدريجياً.",
        "descEn": "Buyid hegemony over Baghdad lasted over a century. The Buyids could not abolish the caliphate despite their Shi'a creed, because the Sunni caliphate's symbolism was deeply rooted in the nation's consciousness. During this period, culture and sciences flourished despite political weakness. Al-Sharif al-Radi (compiler of Nahj al-Balaghah), al-Murtada, and Shaykh al-Tusi emerged among Shi'a scholars, while al-Farabi and Ibn Sina emerged among philosophers. But excessive taxes and internal conflicts among Buyid leaders gradually weakened the state.",
