        "descEn": "Nizam al-Mulk (al-Hasan ibn Ali al-Tusi) was the greatest vizier in Islamic history. He realized that confronting intellectual deviations and Batinid thought could not be done by swords alone, but by knowledge and scholars. So he built the Nizamiyya School in Baghdad — the first organized Islamic university — to spread Sunni jurisprudence and Ash'ari theology. Great imams taught in its schools — al-Juwayni in Nishapur and al-Ghazali in Baghdad. He also built schools in Nishapur, Mosul, and all major cities. His book 'Siyasat Namah' remains a reference in the art of governance.",
