        "descAr": "في ذروة الجهاد الإسلامي، قاد صلاح الدين الأيوبي جيوش المسلمين لتحرير بيت المقدس من الصليبيين. في معركة حطين (583 هـ) حطم صلاح الدين جيش الصليبيين وأسر ملكهم. ثم توجه إلى القدس فتحها بدون مجزرة — عكس ما فعله الصليبيون. عامل صلاح الدين أهلها بإنسانية وكرم، ورد المسجد الأقصى إلى الإسلام. كان صلاح الدين يفعل كل ذلك باسم الخليفة العباسي في بغداد، ويخطب باسمه في المنابر.",
        "descEn": "At the peak of Islamic jihad, Saladin (Salah al-Din al-Ayyubi) led the Muslim armies to liberate Jerusalem from the Crusaders. At the Battle of Hattin (583 AH), Saladin crushed the Crusader army and captured their king. He then marched to Jerusalem and conquered it without massacre — unlike what the Crusaders had done. Saladin treated its inhabitants with humanity and generosity, and restored al-Aqsa Mosque to Islam. Saladin did all this in the name of the Abbasid caliph in Baghdad.",
