        "descEn": "Caliph al-Nasir li-Din Allah assumed the caliphate during a difficult period, but was among the most prominent late Abbasid caliphs. Through political acumen, he restored some caliphal influence in Iraq and weakened Seljuk influence. He reorganized the institution of 'Futuwwa' (chivalric orders) as a social force supporting the caliphate. He tried to approach various powers and employ them for his benefit. But resources were scarce and challenges immense: the emergence of the Khwarazmians and Mongols was beyond any single caliph's capacity.",
