        "descAr": "في بداية القرن السابع الهجري، ظهر تهديد رهيب من أقصى الشرق: جيوش المغول (التتار) بقيادة جنكيز خان. بدأوا باجتياح بلاد ما وراء النهر، فسقطت بخارى وسمرقند في سنوات قليلة. كان التتار محاربين لا يعرفون الرحمة: يقتلون كل من يقاوم، ويهدمون المدن ويحرقونها. وفي حملة جنكيز نفسها سقطت نيسابور ومرو وبلخ، ثم واصل أحفاده التوسع. كانت الدولة الخوارزمية آخر حاجز بينهم وبين العراق، لكنها انهارت بدورها. الآن أصبحت بغداد مكشوفة أمام الخطر المغولي.",
        "descEn": "At the beginning of the 7th century AH, a terrible threat emerged from the farthest East: the Mongol (Tatar) armies under Genghis Khan. They began by invading Transoxiana, and Bukhara and Samarkand fell within a few years. The Tatars were merciless warriors: they killed all who resisted, destroyed cities, and burned them. In Genghis Khan's own campaign Nishapur, Merv, and Balkh fell; his grandsons then continued the expansion. The Khwarazmian state was the last barrier between them and Iraq, but it too collapsed. Now Baghdad lay exposed before the Mongol threat.",
