        "descEn": "In Muharram 656 AH, the Mongol armies under Hulagu Khan reached the walls of Baghdad. Hulagu besieged the city from all sides and placed catapults against the eastern walls. The caliph al-Musta'sim sent negotiators, but Hulagu refused. The greatest betrayal was from within: Vizier Ibn al-Alqami had secretly corresponded with Hulagu, promising to facilitate the Tatars' entry, while simultaneously discouraging the caliph from mobilizing armies. Due to the reduced army, the defenders could not hold out for more than a few weeks. The eastern walls of Baghdad fell at the 'Burj al-Ajami' (Persian Tower).",
