        "lessonAr": "الأمم التي لا تحمي تراثها وعلماءها تفقد هويتها — سقوط بغداد درس في أن الحضارة تحتاج أمناً وعدلاً لتحيا",
        "lessonEn": "Nations that fail to protect their heritage and scholars lose their identity — the fall of Baghdad teaches that civilization needs security and justice to survive",
