        "distEn": "📍 From Söğüt to the world",
        "descAr": "في أواخر القرن السابع الهجري، خرجت من شمال غرب الأناضول إمارة صغيرة بقيادة عثمان بن أرطغرل. كانت هذه الإمارة إحدى إمارات الثغور التي تعيش على الجهاد ضد البيزنطيين. لم يكن أحد يتصور أن هذه البذرة الصغيرة ستتحول خلال قرنين إلى دولة تمتد من بودابست إلى بغداد، ومن القرم إلى القاهرة والجزائر. قام عثمان الأول بتأسيس إمارته على أساس عقيدة الجهاد في سبيل الله وتأمين ثغور المسلمين، وأرسى مبدأ التسامح مع الرعايا غير المسلمين، وجذب المجاهدين من جميع أنحاء الأناضول للانضمام إلى رايته. كان عثمان رجلاً صالحاً عادلاً، يحترم العلماء ويستشيرهم، وكان شديد التمسك بالشريعة.",
        "descEn": "In the late 7th century AH, a small beylik emerged from northwestern Anatolia led by Osman ibn Ertuğrul. This was one of many frontier emirates living on jihad against the Byzantines. No one imagined that this tiny seed would become an empire stretching from Budapest to Baghdad, from Crimea to Cairo and Algiers. Osman I founded his principality on the creed of jihad and securing the frontiers of the Muslims, establishing tolerance toward non-Muslim subjects and attracting fighters from all over Anatolia to his banner. Osman was a righteous, just man who respected scholars and was deeply committed to sharia.",
