        "descAr": "بعد تأسيس الإمارة، شرع عثمان الأول في بناء مؤسسات الدولة الناشئة. اعتمد على مبدأ الشورى في إدارة شؤون الحكم، وأسس نظاماً قضائياً يستند إلى الشريعة الإسلامية. كان التسامح الديني سمة بارزة في حكمه، حيث عامل النصارى واليهود بالعدل والإنصاف، وترك لهم حرية ممارسة شعائرهم. جذب سياسة عثمان العادلة العديد من القبائل التركية والمجاهدين من مختلف أنحاء الأناضول للانضمام إليه. كما اهتم بالاقتصاد فأقام الأسواق وشجع الزراعة والتجارة. وضع عثمان بذلك الأسس المتينة التي قامت عليها الدولة لأكثر من ستة قرون.",
