        "descAr": "أورخان بن عثمان أول من نظم الجيش العثماني نظامياً. أنشأ قوات المشاة (البيادة) والفرسان النظاميين، وأسس فرقة الإنكشارية التي أصبحت نواة الجيش العثماني لقرون. نقل العاصمة من سوغوت إلى بورصة (أول عاصمة إسلامية في غرب الأناضول) بعد فتحها عام 726 هـ. كما أصدر أول عملة عثمانية فضية (الآقجه) مما عزز الاقتصاد. تولى أخوه علاء الدين باشا منصب الصدر الأعظم (أول وزير) ونظم شؤون الدولة المدنية. في عهده توسعت الدولة غرباً نحو البلقان.",
        "descEn": "Orhan ibn Osman was the first to organize the Ottoman army systematically. He established infantry and regular cavalry forces and founded the Janissary corps, which became the core of the Ottoman army for centuries. He moved the capital from Söğüt to Bursa (the first Islamic capital in western Anatolia) after its conquest in 726 AH. He also minted the first Ottoman silver coin (akçe), strengthening the economy. His brother Alaeddin Pasha served as the first grand vizier, organizing civil affairs. During his reign, the state expanded westward toward the Balkans.",
