        "descEn": "Bayezid I, called Yıldırım (the Thunderbolt) for his swift military movements, achieved at the Battle of Nicopolis (1396) a crushing victory over the largest united European army to that date, comprising knights from France, Germany, Hungary, and Wallachia under King Sigismund of Hungary. Bayezid led his army personally and won a great victory, capturing thousands of European knights. He demanded ransoms, collecting enormous sums spent on jihad and expansion. This battle made the Ottoman state a force to be reckoned with on the international stage.",
