        "descAr": "في معركة أنقرة (1402) واجه بايزيد تيمورلنك (تيمور الأعرج) الذي قاد جيشاً ضخماً من آسيا الوسطى. كانت الهزيمة مدمرة، وأُسر بايزيد وتوفي في الأسر. تلت ذلك فترة فتنة (1402–1413) تنازع فيها أبناء بايزيد الأربعة — عيسى، موسى، سليمان، ومحمد — على السلطة، مما أوشك أن يمزق الدولة. انقسمت الإمارة إلى أقسام متناحرة، وبدا أن الحلم العثماني قد انتهى. لكن إرادة الله كانت أقوى، فخرج من هذه الفتنة محمد جلبي موحداً للدولة.",
        "descEn": "At the Battle of Ankara (1402), Bayezid faced Timur (Tamerlane) who led a huge army from Central Asia. The defeat was devastating; Bayezid was captured and died in captivity. This was followed by the Ottoman Interregnum (1402–1413) as Bayezid's four sons — İsa, Musa, Süleyman, and Mehmed — fought for power, nearly tearing the state apart. The emirate was divided into warring factions, and the Ottoman dream seemed to have ended. But Allah's will was stronger, and from this turmoil emerged Mehmed Çelebi as the unifier of the state.",
