        "descAr": "بعد الفتنة، تولى محمد الأول (محمد جلبي) الحكم وبدأ في توحيد الدولة واستعادة قوتها. حكم 8 سنوات فقط لكنه كان مؤسس النهضة الثانية للدولة. خلفه ابنه مراد الثاني الذي قاد توسعاً كبيراً في البلقان: فتح سالونيك (1430)، وهزم التحالف الأوروبي في معركة فارنا (1444) بقيادة الصدر الأعظم خليل باشا. كان مراد الثاني حاكماً عادلاً متواضعاً، تنازل عن العرش ثم عاد إليه عندما استدعته الأمة. في عهده أرسيت أسس الجيش والنظام التي مهدت للفتح العظيم.",
        "descEn": "After the interregnum, Mehmed I (Mehmed Çelebi) took power and began reunifying the state and restoring its strength. He ruled only 8 years but was the founder of the state's second renaissance. He was succeeded by his son Murad II, who led major Balkan expansion: conquering Salonica (1430) and defeating the European coalition at the Battle of Varna (1444) under Grand Vizier Halil Pasha. Murad II was a just and humble ruler who abdicated and then returned when the nation called him. His reign laid the foundations for the great conquest.",
