        "distAr": "📍 إسطنبول — القسطنطينية",
        "distEn": "📍 Istanbul — Constantinople",
        "descAr": "تولى محمد الثاني (الفاتح) الحكم وعمره 21 سنة، رغم معارضة الصدر الأعظم خليل باشا الذي كان يفضل أخاه الأكبر. كان محمد شاباً مثقفاً يجيد عدة لغات، عالماً في العلوم والفلسفة والفنون العسكرية. توجه فوراً لتحقيق حلم أجداده: فتح القسطنطينية. بنى قلعة روملي حصار على الضفة الأوروبية للبوسفور في 4 أشهر فقط، ليقابل قلعة الأناضول حصار التي بناها جده بايزيد. قطعت القلعتان خطوط الإمداد عن المدينة. أعد محمد أسطولاً ضخماً ومدافع هائلة (بما فيها المدفع العملاق لأوربان المجري)، واستعد جيشه البالغ 100 ألف جندي لخوض أعظم حصار في التاريخ.",
        "descEn": "Mehmed II (the Conqueror) ascended the throne at age 21, despite opposition from Grand Vizier Halil Pasha who favored his elder brother. Mehmed was a cultured youth fluent in several languages, learned in sciences, philosophy, and military arts. He immediately set out to fulfill his ancestors' dream: the conquest of Constantinople. He built Rumeli Hisarı fortress on the European shore of the Bosphorus in just 4 months, facing the Anadolu Hisarı built by his grandfather Bayezid. The twin fortresses cut the city's supply lines. Mehmed prepared a huge fleet and massive cannons (including the giant bombard of the Hungarian Urban), and his army of 100,000 soldiers prepared for the greatest siege in history.",
