        "descAr": "بعد الفتح مباشرة بدأ محمد الفاتح في تحويل القسطنطينية إلى عاصمة إسلامية: إسطنبول. بنى جامع الفاتح الكبير والمجمع العلمي الملحق به — أول جامعة إسلامية منظمة تضم مدارس في الفقه والطب والفلك والرياضيات. شجع الهجرة إليها من جميع أنحاء العالم الإسلامي. أسس نظام الملل (الطوائف) الذي نظم حياة غير المسلمين — الروم والأرمن واليهود — في إطار قانوني يحمي حريتهم الدينية مقابل الجزية. أعاد بناء المدينة بعد الدمار، وشق الطرق، وبنى المساجد والأسواق والحمامات. جعل من إسطنبول درة المدن الإسلامية.",
        "descEn": "Immediately after the conquest, Mehmed the Conqueror began transforming Constantinople into an Islamic capital: Istanbul. He built the great Fatih Mosque and its attached educational complex — the first organized Islamic university with schools of fiqh, medicine, astronomy, and mathematics. He encouraged migration from all over the Islamic world. He established the millet system, organizing the lives of non-Muslims — Romans, Armenians, and Jews — within a legal framework protecting their religious freedom in exchange for jizya. He rebuilt the city, opened roads, and built mosques, markets, and bathhouses. He made Istanbul the jewel of Islamic cities.",
