        "descEn": "Mehmed the Conqueror continued his conquests after Constantinople. He conquered Serbia, annexed Bosnia and Herzegovina and Albania after the heroic resistance of Skanderbeg (who later returned to Ottoman suzerainty). He subjugated the Crimean Khanate and made it a vassal, making the Black Sea entirely an 'Ottoman lake'. He captured important Black Sea ports including Caffa and Trebizond. By his reign, the Ottoman state reached its greatest extent in the 15th century. He organized the conquests into provinces (eyalets) and established a tight administrative system.",
