        "distEn": "📍 From Chaldiran to Cairo",
        "descAr": "سليم الأول — الملقب بياووز (الشديد) — قاد حملة عسكرية غيرت وجه العالم الإسلامي. في معركة جالديران (920 هـ/1514 م) حطم الجيش الصفوي بقيادة الشاه إسماعيل. ثم توجه جنوباً، وفي معركة مرج دابق (922 هـ) ضد المماليك دخل حلب ودمشق. وفي معركة الريدانية (923 هـ) دخل القاهرة وأعدم طومان باي آخر سلاطين المماليك. بذلك ضم سليم الشام ومصر والحجاز إلى الدولة العثمانية، موحداً بذلك معظم المشرق الإسلامي تحت راية واحدة لأول مرة منذ سقوط الخلافة العباسية.",
        "descEn": "Selim I — called Yavuz (the Stern) — led a military campaign that changed the face of the Islamic world. At the Battle of Chaldiran (920 AH/1514 CE), he crushed the Safavid army of Shah Ismail. He then turned south, defeated the Mamluks at Marj Dabiq (922 AH), entering Aleppo and Damascus. At the Battle of Raydaniyya (923 AH), he entered Cairo and executed Tumanbay, the last Mamluk sultan. Thus Selim annexed Syria, Egypt, and Hejaz to the Ottoman state, unifying most of the Islamic East under one banner for the first time since the fall of the Abbasid caliphate.",
