        "descAr": "بعد ضم مصر، تسلم سليم الأول مفاتيح الحرمين الشريفين من الشريف بركات أمير مكة. وأعلن انتقال الخلافة الإسلامية من بني العباس (آخرهم زين الدين زكريا بمصر) إلى بني عثمان. أصبح السلطان العثماني خليفة المسلمين وقائد الأمة. تولت الدولة حماية طرق الحج وأمن الحجاج، وأسست نظاماً متكاملاً لخدمة الحرمين — إرسال المحمل الشريف سنوياً من القاهرة وإسطنبول، وعمارة المسجد الحرام والمسجد النبوي. أصبحت الدولة العثمانية بذلك القوة السنية الرائدة عالمياً وحامية المقدسات.",
        "descEn": "After the annexation of Egypt, Selim I received the keys of the two holy sanctuaries from Sharif Barakat of Makkah. He proclaimed the transfer of the Islamic caliphate from the Abbasids (the last being Zayn al-Din Zakariyya in Cairo) to the House of Osman. The Ottoman sultan became the Caliph of the Muslims and the leader of the Ummah. The state undertook the protection of Hajj routes and pilgrims' security, establishing an integrated system for serving the Haramayn — sending the sacred caravan (Mahmal) annually from Cairo and Istanbul, and maintaining al-Masjid al-Haram and al-Masjid al-Nabawi. Thus the Ottoman state became the world's leading Sunni power and guardian of the holy sites.",
