        "distEn": "📍 Istanbul — Heart of the Islamic World",
        "descAr": "سليمان القانوني — عاشر سلاطين الدولة وأطولهم حكماً (46 سنة)، بلغت الدولة في عهده أوج قوتها ومجدها. ازدهر الاقتصاد والعلم والعمارة، وامتدت الدولة من المجر إلى اليمن، ومن الجزائر إلى العراق. أسموه 'القانوني' لأنه نظم القوانين المدنية موافقة للشريعة الحنفية في 'قانوننامه' الشهير. كان سليمان شاعراً وأديباً متقناً للفنون، وأقام علاقات دبلوماسية مع الدول الأوروبية. اتسع نفوذ العلماء والمفتين وكان المفتي أبو السعود أفندي المرجع الأعلى للدولة. عُرف عصره بالعدل والرخاء والازدهار الحضاري.",
        "descEn": "Suleiman the Lawgiver — the 10th sultan and longest-reigning (46 years). The state reached its peak of power and glory during his reign. The economy, science, and architecture flourished, and the state stretched from Hungary to Yemen, from Algeria to Iraq. He was called 'al-Qanuni' for codifying civil laws in accordance with Hanafi sharia in the famous 'Qanunname'. Suleiman was a poet, a literary figure skilled in the arts, and established diplomatic relations with European states. The influence of scholars and jurists expanded, with Shaykh al-Islam Abu al-Su'ud Efendi as the highest authority. His era was known for justice, prosperity, and cultural flourishing.",
