        "descEn": "Under Suleiman, Ottoman conquests reached their greatest extent in Europe. Belgrade (1521) was conquered as the gateway to Hungary, then Rhodes (1522) after a heroic siege expelled the Knights Hospitaller. At the Battle of Mohács (1526), the Hungarian army was completely destroyed, and Budapest and Hungary were opened. Vienna was besieged (1529) but did not fall. In the Mediterranean, Hayreddin Barbarossa Pasha led the Ottoman fleet to victory at the Battle of Preveza (1538) against the united European fleet, making the Mediterranean an Ottoman lake. Tripoli (1551) and Tunis were conquered. The Ottoman state became the sole superpower of the world.",
