        "descAr": "أبو السعود أفندي — أكبر مفتٍ في التاريخ العثماني. شغل منصب مفتي الدولة (شيخ الإسلام) لمدة 30 عاماً، وأحدث ثورة في العلاقة بين الشريعة والقانون الوضعي. أشرف على إصدار 'قانوننامه' الذي نظم الأراضي والضرائب والجرائم والعقوبات موافقاً للفقه الحنفي. كان الظل الشرعي للسلطان — نموذج الحاكم الذي يستشير العلماء. ترسخ المذهب الحنفي كمذهب رسمي للدولة، وانتشرت محاكم الشرع في جميع أنحاء الإمبراطورية. نظام أبو السعود أصبح مرجعاً للحكم الإسلامي لقرون.",
        "descEn": "Abu al-Su'ud Efendi — the greatest mufti in Ottoman history. He served as Shaykh al-Islam for 30 years and revolutionized the relationship between sharia and positive law. He oversaw the Qanunname, which regulated land, taxes, crimes, and punishments in accordance with Hanafi fiqh. He was the legal shadow of the sultan — a model of the ruler consulting scholars. The Hanafi school became the official madhhab of the state, and sharia courts spread throughout the empire. Abu al-Su'ud's system became a reference for Islamic governance for centuries.",
