        "descEn": "The Janissaries — once the core of the Ottoman fighting force — became a corrupt power exploiting the state. They deposed sultans and appointed whom they wished, killing grand viziers who displeased them. Sultan Osman II was assassinated (1622) by them because he tried to reform the army. Sultan Ibrahim I was deposed (1648) and executed. The state became hostage to this rebellious military force that grew stronger as the state weakened. This was a grave lesson in the consequences of leaving the military institution without sharia and political oversight.",
