        "descEn": "Murad IV ascended the throne at age 11, when the state was at its worst state of chaos and Janissary rebellion. Murad was known for his physical strength (strongest of all Ottoman sultans) and his severity in imposing order. He executed hundreds of rebels and transgressors, banning alcohol and tobacco in Istanbul (the famous prohibition). In 1638 he led a campaign eastward and reconquered Baghdad from the Safavids after a heroic siege in which his grand vizier Tayyar Mehmed Pasha was martyred. Murad temporarily restored the state's prestige, but his reforms died with his early death.",
