        "descAr": "آل كوبريلي — أسرة من الصدور العظام أنقذت الدولة من الانهيار في القرن الحادي عشر الهجري. بدأها محمد باشا كوبريلي (1066 هـ) بإصلاحات جذرية: القضاء على الفساد، إعدام المئات من المفسدين، تنظيم المالية العامة، وإعادة هيبة الدولة. خلفه ابنه أحمد باشا كوبريلي الذي قاد حصار قندية (كانديا) في كريت وفتحها بعد 21 عاماً من الحصار (1079 هـ/1669 م). كانت إصلاحات آل كوبريلي آخر ومضات القوة العثمانية قبل الانحدار الكبير.",
        "descEn": "The Köprülü family — a dynasty of grand viziers who saved the state from collapse in the 11th century AH. It began with Köprülü Mehmed Pasha (1066 AH) with radical reforms: eliminating corruption, executing hundreds of corrupt officials, reorganizing public finances, and restoring the state's prestige. He was succeeded by his son Ahmed Köprülü Pasha, who led the siege of Candia in Crete and conquered it after 21 years of siege (1079 AH/1669 CE). The Köprülü reforms were the last flashes of Ottoman strength before the great decline.",
