        "descAr": "قرر الصدر الأعظم قرة مصطفى باشا فتح فيينا — قرار كان خطأ استراتيجياً فادحاً. حاصر الجيش العثماني فيينا 60 يوماً، ولكن بدلاً من اقتحامها فوراً، ضيع الوقت في الحصار الطويل. وصل جيش النجدة البولندي بقيادة الملك يان سوبياسكي وهاجم العثمانيين من الخلف. كانت الهزيمة ساحقة. في معاهدة كارلوفجة (1699) فقدت الدولة المجر وترانسيلفانيا وبودابست — أول خسارة كبرى للأراضي. بدأ الانحسار المنهجي للدولة بعد 400 عام من التوسع.",
        "descEn": "Grand Vizier Kara Mustafa Pasha decided to conquer Vienna — a disastrous strategic error. The Ottoman army besieged Vienna for 60 days, but instead of storming it immediately, wasted time in a long siege. The Polish relief army under King Jan Sobieski arrived and attacked the Ottomans from the rear. The defeat was devastating. By the Treaty of Karlowitz (1699), the state lost Hungary, Transylvania, and Buda — the first major territorial loss. The systematic retreat of the state began after 400 years of expansion.",
