        "descEn": "After the Vienna defeat, the state began losing the initiative. The 'Eastern Question' began — continuous European intervention in the state's affairs. European states were granted 'capitulations' (commercial concessions) they exploited to penetrate the Ottoman economy. By the Treaty of Küçük Kaynarca (1774), Russia gained the right to protect Orthodox Christians in the state. French and British influence rose, and European military superiority became evident. The state transformed from a dominant power to 'the Sick Man of Europe' — a phrase that described the state's growing weakness.",
