        "descEn": "Mahmud II — the sultan who dared what his predecessors could not: abolishing the Janissaries. In the 'Auspicious Event' (1826), loyal forces besieged the Janissary barracks at Atmeydanı (Horse Square) and killed thousands of them. This ended centuries of corruption by this institution that had been a dagger in the state's back. Mahmud began the Tanzimat era — an attempt to modernize the army and administration on the European model. But his modernization came with Western imitation that weakened the position of scholars and traditional Islamic institutions — a heavy price paid by the state's Islamic identity.",
