        "descEn": "The Tanzimat — a series of reforms beginning with the Gülhane Edict (1839) proclaiming legal equality between all subjects, Muslims and non-Muslims. It was followed by the Imperial Edict (1856) expanding freedoms. Civil law was modernized in the 'Majalla' — the first Islamic codification of civil law. Modern schools and the Ottoman university were founded. The Tanzimat attempted to save the state by mixing sharia with European laws. But the lesson was harsh: partial Westernization did not save the state but rather increased division among society and weakened Islamic identity.",
