        "descAr": "جمعية الاتحاد والترقي — تنظيم سري بدأ كحركة معارضة ثم تحول إلى دكتاتورية عسكرية. في ثورة 1908 أجبروا السلطان عبد الحميد على إعادة الدستور، وفي 1909 عزلوه ونفوه. سيطروا على الدولة بثلاثة قادة: طلعت باشا (الداخلية)، أنور باشا (الحربية)، جمال باشا (البحرية). اتبعوا توجه علمانياً متطرفاً يقلد الغرب، وهمشوا الشريعة والعلماء. قراراهم الكارثية — دخول الحرب العالمية إلى جانب ألمانيا، وتهميش الهوية الإسلامية — عجلت بتفكيك الدولة. الدرس المؤلم: الانبهار بالغرب والابتعاد عن الإسلام لم ينقذ الدولة بل دمرها.",
        "descEn": "The Committee of Union and Progress (CUP) — a secret organization that began as an opposition movement then turned into a military dictatorship. In the 1908 Revolution, they forced Sultan Abdul Hamid to restore the constitution, and in 1909 they deposed and exiled him. Three leaders controlled the state: Talat Pasha (Interior), Enver Pasha (War), and Cemal Pasha (Navy). They followed an extreme secularist direction imitating the West, marginalizing sharia and scholars. Their disastrous decisions — entering World War I alongside Germany and marginalizing Islamic identity — hastened the dismantling of the state. The painful lesson: fascination with the West and distancing from Islam did not save the state but destroyed it.",
