        "descEn": "Enver Pasha's decision to enter World War I alongside Germany was a disaster. The state proclaimed holy jihad (fatwa of jihad against the Allies) and millions of Muslims rallied. At Gallipoli (1915), the Ottomans achieved their greatest naval victory under Mustafa Kemal (who would later become the enemy of the caliphate). But in the Caucasus it was a catastrophe. In Syria — Sharif Husayn ibn Ali, Amir of Makkah, joined the British (the Great Arab Revolt) in betrayal of the caliphate. Jerusalem was occupied (1917). In 1918, the state signed the Armistice of Mudros — the effective end of the state.",
