        "descAr": "في 3 مارس 1924 — 27 رجب 1342 هـ — أصدرت الجمعية الوطنية التركية بقيادة مصطفى كمال قراراً بإلغاء الخلافة الإسلامية. كان هذا أقسى ضربة للإسلام منذ سقوط بغداد. ألغيت الخلافة التي دامت 625 عاماً، وطرد آخر الخلفاء عبد المجيد الثاني وآل عثمان من وطنهم. احتلت إسطنبول بالقوات البريطانية (1918–1923)، ثم انتقلت العاصمة إلى أنقرة. أعلنت الجمهورية التركية (1923). انتهى بذلك أعظم درس في سنن الله في تغيير الأمم: 'إن الله لا يغير ما بقوم حتى يغيروا ما بأنفسهم'.",
        "descEn": "On 3 March 1924 — 27 Rajab 1342 AH — the Turkish Grand National Assembly under Mustafa Kemal issued a decree abolishing the Islamic caliphate. This was the harshest blow to Islam since the fall of Baghdad. The caliphate that had lasted 625 years was abolished, and the last caliph Abdulmejid II and the House of Osman were expelled from their homeland. Istanbul was occupied by British forces (1918–1923), then the capital moved to Ankara. The Turkish Republic was proclaimed (1923). Thus ended the greatest lesson in Allah's sunnah of changing nations: 'Indeed, Allah does not change the condition of a people until they change what is in themselves.'",
